// Generated by a script from test_ir_check.py's cases and one case for
// each raise site of passes/ir_check.py: the dump of each input and the
// message Python's `ir_check` gives for it, after "test" (empty when
// nothing is raised). test_ir_check.cpp runs them.
#pragma once

#include <optional>
#include <string_view>
#include <vector>

namespace c6502::testing::ir_check_cases {

using Names = std::vector<std::string_view>;

// One check of a TAC function: its dump, the names of its symbol table
// (each an `int` local, or no table), its SSA names (none outside SSA
// form), whether the checks are on, and Python's message.
struct TacCheck {
  std::string_view fn;
  std::optional<Names> symbols;
  std::optional<Names> ssa;
  bool on;
  std::string_view message;
};

// One check of an asm program, with `pseudos` and `phis`.
struct AsmCheck {
  std::string_view prog;
  bool pseudos;
  bool phis;
  std::string_view message;
};

// The problems of an asm2 list of instructions, which
// `decimal_region_problems` gives, joined by "; ".
struct RegionCheck {
  std::string_view instrs;
  std::string_view problems;
};

// One check of an asm2 program.
struct Asm2Check {
  std::string_view prog;
  std::string_view message;
};

template <class T>
struct Case {
  std::string_view name;
  std::vector<T> checks;
};

inline const std::vector<Case<TacCheck>>& tac_cases() {
  static const std::vector<Case<TacCheck>> cases = {
      // A function in SSA form with nothing wrong.
      {"good_ssa",
       {
           {R"~(Function("f" true ["p"] [
  Copy(Constant(ConstInt(1)) Var("a.1"))
  Binary(Add Var("a.1") Var("p") Var("b.1"))
  Ret(Var("b.1"))
])
)~",
            Names{"a.1", "b.1", "p"},
            Names{"a.1", "b.1", "p"},
            true,
            R"~()~"},
       }},
      // The shape of the bug where a second narrowing dropped the first one's
      // Truncate: the narrow Binary reads a temporary nothing defines any more.
      {"read_of_undefined_ssa_name",
       {
           {R"~(Function("f" true [] [
  Binary(Multiply Var("t.lo1") Constant(ConstInt(3)) Var("d"))
  Ret(Var("d"))
])
)~",
            Names{"t.lo1", "d"},
            Names{"d", "t.lo1"},
            true,
            R"~(after test, function 'f': Binary reads t.lo1, which nothing defines)~"},
       }},
      {"read_before_definition",
       {
           {R"~(Function("f" true [] [
  Copy(Var("a.1") Var("b.1"))
  Copy(Constant(ConstInt(1)) Var("a.1"))
  Ret(None)
])
)~",
            Names{"a.1", "b.1"},
            Names{"a.1", "b.1"},
            true,
            R"~(after test, function 'f': Copy reads a.1 before its definition)~"},
       }},
      {"definition_doesnt_dominate",
       {
           {R"~(Function("f" true ["p"] [
  JumpIfTrue(Var("p") "L")
  Copy(Constant(ConstInt(1)) Var("a.1"))
  Label("L")
  Ret(Var("a.1"))
])
)~",
            Names{"a.1", "p"},
            Names{"a.1", "p"},
            true,
            R"~(after test, function 'f': Ret reads a.1, whose definition doesn't dominate it)~"},
       }},
      {"ssa_name_defined_twice",
       {
           {R"~(Function("f" true [] [
  Copy(Constant(ConstInt(1)) Var("a.1"))
  Copy(Constant(ConstInt(2)) Var("a.1"))
  Ret(None)
])
)~",
            Names{"a.1"},
            Names{"a.1"},
            true,
            R"~(after test, function 'f': SSA name a.1 defined twice)~"},
       }},
      // SSA renaming never visits a block nothing reaches.
      {"unreachable_block_ignored",
       {
           {R"~(Function("f" true ["p"] [
  Ret(Var("p"))
  Copy(Constant(ConstInt(1)) Var("p"))
  Ret(None)
])
)~",
            Names{"p"},
            Names{"p"},
            true,
            R"~()~"},
       }},
      {"labels",
       {
           {R"~(Function("f" true [] [
  Jump("L")
  Ret(None)
])
)~",
            Names{},
            std::nullopt,
            true,
            R"~(after test, function 'f': jump to missing label L)~"},
           {R"~(Function("f" true [] [
  Label("L")
  Label("L")
  Ret(None)
])
)~",
            Names{},
            std::nullopt,
            true,
            R"~(after test, function 'f': label L defined twice)~"},
       }},
      {"name_missing_from_symbols",
       {
           {R"~(Function("f" true [] [
  Copy(Constant(ConstInt(1)) Var("x"))
  Ret(None)
])
)~",
            Names{},
            std::nullopt,
            true,
            R"~(after test, function 'f': x isn't in the symbol table)~"},
       }},
      {"undefined_temporary_outside_ssa",
       {
           {R"~(Function("f" true [] [
  Ret(Var("%3"))
])
)~",
            Names{"%3"},
            std::nullopt,
            true,
            R"~(after test, function 'f': Ret reads %3, which nothing defines)~"},
       }},
      // a.1 = 0; L: b.1 = Phi(a.1 from E, b.2 from B); B: b.2 = b.1 + 1;
      // jump L. The block before L is labelled E.
      {"good_loop",
       {
           {R"~(Function("f" true [] [
  Label("E")
  Copy(Constant(ConstInt(0)) Var("a.1"))
  Label("L")
  Phi(Var("b.1") [PhiArg("E" Var("a.1")) PhiArg("B" Var("b.2"))])
  JumpIfTrue(Var("b.1") "X")
  Label("B")
  Binary(Add Var("b.1") Constant(ConstInt(1)) Var("b.2"))
  Jump("L")
  Label("X")
  Ret(Var("b.1"))
])
)~",
            Names{"a.1", "b.1", "b.2"},
            Names{"a.1", "b.1", "b.2"},
            true,
            R"~()~"},
       }},
      {"phi_argument_from_missing_label",
       {
           {R"~(Function("f" true [] [
  Label("E")
  Copy(Constant(ConstInt(0)) Var("a.1"))
  Label("L")
  Phi(Var("b.1") [PhiArg("E" Var("a.1")) PhiArg("Q" Var("b.2"))])
  JumpIfTrue(Var("b.1") "X")
  Label("B")
  Binary(Add Var("b.1") Constant(ConstInt(1)) Var("b.2"))
  Jump("L")
  Label("X")
  Ret(Var("b.1"))
])
)~",
            Names{"a.1", "b.1", "b.2"},
            Names{"a.1", "b.1", "b.2"},
            true,
            R"~(after test, function 'f': Phi argument from missing label Q)~"},
       }},
      // b.2 is defined in B, which doesn't dominate the end of E.
      {"phi_argument_not_dominated_at_its_predecessor",
       {
           {R"~(Function("f" true [] [
  Label("E")
  Copy(Constant(ConstInt(0)) Var("a.1"))
  Label("L")
  Phi(Var("b.1") [PhiArg("E" Var("b.2")) PhiArg("B" Var("b.2"))])
  JumpIfTrue(Var("b.1") "X")
  Label("B")
  Binary(Add Var("b.1") Constant(ConstInt(1)) Var("b.2"))
  Jump("L")
  Label("X")
  Ret(Var("b.1"))
])
)~",
            Names{"a.1", "b.1", "b.2"},
            Names{"a.1", "b.1", "b.2"},
            true,
            R"~(after test, function 'f': Phi reads b.2, whose definition doesn't dominate it)~"},
       }},
      // The second function has the first one's labels and jumps, so its
      // blocks come from the first check, and its own reads are still checked.
      {"same_control_flow_other_body",
       {
           {R"~(Function("f" true [] [
  Label("E")
  Copy(Constant(ConstInt(0)) Var("a.1"))
  Label("L")
  Phi(Var("b.1") [PhiArg("E" Var("a.1")) PhiArg("B" Var("b.2"))])
  JumpIfTrue(Var("b.1") "X")
  Label("B")
  Binary(Add Var("b.1") Constant(ConstInt(1)) Var("b.2"))
  Jump("L")
  Label("X")
  Ret(Var("b.1"))
])
)~",
            Names{"a.1", "b.1", "b.2"},
            Names{"a.1", "b.1", "b.2"},
            true,
            R"~()~"},
           {R"~(Function("f" true [] [
  Label("E")
  Copy(Constant(ConstInt(0)) Var("a.1"))
  Label("L")
  Phi(Var("b.1") [PhiArg("E" Var("a.1")) PhiArg("B" Var("b.2"))])
  JumpIfTrue(Var("b.1") "X")
  Label("B")
  Binary(Add Var("c.1") Constant(ConstInt(1)) Var("b.2"))
  Jump("L")
  Label("X")
  Ret(Var("b.1"))
])
)~",
            Names{"a.1", "b.1", "b.2", "c.1"},
            Names{"a.1", "b.1", "b.2", "c.1"},
            true,
            R"~(after test, function 'f': Binary reads c.1, which nothing defines)~"},
       }},
      // The blocks of the first check mustn't be used for the second, whose
      // jump goes to L. a.1's definition then no longer dominates L.
      {"jump_changed_in_place",
       {
           {R"~(Function("f" true ["p"] [
  Label("E")
  JumpIfTrue(Var("p") "M")
  Copy(Constant(ConstInt(1)) Var("a.1"))
  Label("L")
  Ret(Var("a.1"))
  Label("M")
  Ret(Var("p"))
])
)~",
            Names{"a.1", "p"},
            Names{"a.1", "p"},
            true,
            R"~()~"},
           {R"~(Function("f" true ["p"] [
  Label("E")
  JumpIfTrue(Var("p") "L")
  Copy(Constant(ConstInt(1)) Var("a.1"))
  Label("L")
  Ret(Var("a.1"))
  Label("M")
  Ret(Var("p"))
])
)~",
            Names{"a.1", "p"},
            Names{"a.1", "p"},
            true,
            R"~(after test, function 'f': Ret reads a.1, whose definition doesn't dominate it)~"},
       }},
      {"every_problem_is_reported",
       {
           {R"~(Function("f" true [] [
  Copy(Var("%1") Var("x"))
  Copy(Var("%2") Var("y"))
  Ret(Var("%2"))
])
)~",
            Names{"%1", "%2", "x", "y"},
            std::nullopt,
            true,
            R"~(after test, function 'f': Copy reads %1, which nothing defines; Copy reads %2, which nothing defines; Ret reads %2, which nothing defines)~"},
           {R"~(Function("f" true [] [
  Copy(Var("%1") Var("x"))
  Copy(Var("%2") Var("y"))
  Ret(Var("%2"))
])
)~",
            Names{"%1", "y"},
            std::nullopt,
            true,
            R"~(after test, function 'f': %2 isn't in the symbol table; x isn't in the symbol table)~"},
       }},
      {"temporary_in_memory_needs_no_definition",
       {
           {R"~(Function("f" true [] [
  GetAddress(Var("%1") Var("p"))
  Ret(Var("%1"))
])
)~",
            Names{"%1", "p"},
            std::nullopt,
            true,
            R"~()~"},
       }},
      {"off_by_default",
       {
           {R"~(Function("f" true [] [
  Jump("L")
])
)~",
            Names{},
            std::nullopt,
            false,
            R"~()~"},
       }},
      // A Phi argument's name with no definition anywhere.
      {"phi_reads_what_nothing_defines",
       {
           {R"~(Function("f" true [] [
  Label("E")
  Copy(Constant(ConstInt(0)) Var("a.1"))
  Label("L")
  Phi(Var("b.1") [PhiArg("E" Var("a.1")) PhiArg("B" Var("z.1"))])
  JumpIfTrue(Var("b.1") "X")
  Label("B")
  Binary(Add Var("b.1") Constant(ConstInt(1)) Var("b.2"))
  Jump("L")
  Label("X")
  Ret(Var("b.1"))
])
)~",
            Names{"a.1", "b.1", "b.2", "z.1"},
            Names{"a.1", "b.1", "b.2", "z.1"},
            true,
            R"~(after test, function 'f': Phi reads z.1, which nothing defines)~"},
       }},
      {"five_problems_at_most",
       {
           {R"~(Function("f" true [] [
  Copy(Var("%0") Var("x"))
  Copy(Var("%1") Var("x"))
  Copy(Var("%2") Var("x"))
  Copy(Var("%3") Var("x"))
  Copy(Var("%4") Var("x"))
  Copy(Var("%5") Var("x"))
  Copy(Var("%6") Var("x"))
  Ret(None)
])
)~",
            Names{"%0", "%1", "%2", "%3", "%4", "%5", "%6", "x"},
            std::nullopt,
            true,
            R"~(after test, function 'f': Copy reads %0, which nothing defines; Copy reads %1, which nothing defines; Copy reads %2, which nothing defines; Copy reads %3, which nothing defines; Copy reads %4, which nothing defines)~"},
       }},
      // Without a symbol table no name is looked up.
      {"no_symbol_table",
       {
           {R"~(Function("f" true [] [
  Copy(Constant(ConstInt(1)) Var("x"))
  Ret(None)
])
)~",
            std::nullopt,
            std::nullopt,
            true,
            R"~()~"},
       }},
      // An object indexed by name is in memory.
      {"indexed_by_name_needs_no_definition",
       {
           {R"~(Function("f" true [] [
  IndexedLoad("%1" Constant(ConstInt(0)) Var("y") false 0 0)
  IndexedSymbolStore("%2" Constant(ConstInt(0)) Var("%2") false 0)
  Ret(None)
])
)~",
            Names{"%1", "%2", "y"},
            std::nullopt,
            true,
            R"~()~"},
       }},
      // Each kind of jump names its target.
      {"jump_kinds",
       {
           {R"~(Function("f" true [] [
  JumpIfFalse(Constant(ConstInt(1)) "A")
  JumpIfCmp(Equal Constant(ConstInt(1)) Constant(ConstInt(2)) "B")
  JumpIfMasked(Constant(ConstInt(1)) 1 true "C")
  Ret(None)
])
)~",
            Names{},
            std::nullopt,
            true,
            R"~(after test, function 'f': jump to missing label A; jump to missing label B; jump to missing label C)~"},
       }},
      // A parameter's first SSA value is defined at entry.
      {"parameter_defined_again",
       {
           {R"~(Function("f" true ["p"] [
  Copy(Constant(ConstInt(1)) Var("p"))
  Ret(Var("p"))
])
)~",
            Names{"p"},
            Names{"p"},
            true,
            R"~(after test, function 'f': SSA name p defined twice)~"},
       }},
  };
  return cases;
}

inline const std::vector<Case<AsmCheck>>& asm_cases() {
  static const std::vector<Case<AsmCheck>> cases = {
      {"pseudo_left",
       {
           {R"~(Program([
  Function("f" true [] [
    Mov(Pseudo("x" 0) Reg(A) false)
  ])
])
)~",
            true, false,
            R"~()~"},
           {R"~(Program([
  Function("f" true [] [
    Mov(Pseudo("x" 0) Reg(A) false)
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': Pseudo left in Mov)~"},
       }},
      {"branch_to_missing_label",
       {
           {R"~(Program([
  Function("f" true [] [
    Branch(EQ ".x")
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': branch to missing label .x)~"},
       }},
      {"tail_call_jump_is_fine",
       {
           {R"~(Program([
  Function("f" true [] [
    Jump("g" [])
  ])
])
)~",
            false, false,
            R"~()~"},
       }},
      {"label_defined_twice",
       {
           {R"~(Program([
  Function("f" true [] [
    Label(".a")
    Label(".a")
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': label .a defined twice)~"},
       }},
      {"jump_to_missing_local_label",
       {
           {R"~(Program([
  Function("f" true [] [
    Jump(".x" [])
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': jump to missing label .x)~"},
       }},
      // A target that isn't local is another function's.
      {"jump_table_to_missing_label",
       {
           {R"~(Program([
  Function("f" true [] [
    JumpTable("t" "Y" 0 [".a" "g" ".b"])
    Label(".a")
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': jump table to missing label .b)~"},
       }},
      {"phi_outside_ssa",
       {
           {R"~(Program([
  Function("f" true [] [
    Phi(Pseudo("x" 0) [])
  ])
])
)~",
            true, false,
            R"~(after test, function 'f': Phi outside SSA form)~"},
           {R"~(Program([
  Function("f" true [] [
    Phi(Pseudo("x" 0) [])
  ])
])
)~",
            true, true,
            R"~()~"},
       }},
      {"decimal_arith_forms",
       {
           {R"~(Program([
  Function("f" true [] [
    DecimalArith(false [Reg(X) Data("a" 1)] [Imm(1)] [Imm(2) IndirectZpY(128)])
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': DecimalArith has 2 left, 1 right, and 2 dst bytes; DecimalArith reads Reg; DecimalArith writes Imm; DecimalArith writes IndirectZpY)~"},
           {R"~(Program([
  Function("f" true [] [
    DecimalArith(true [] [] [])
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': DecimalArith has 0 left, 0 right, and 0 dst bytes)~"},
           {R"~(Program([
  Function("f" true [] [
    DecimalArith(true [Frame(1) ImmLabelLow("t" 0)] [ZP(128 0) ImmLabelHigh("t" 0)] [Stack(1) Data("d" 0)])
  ])
])
)~",
            false, false,
            R"~()~"},
       }},
      {"decimal_flag_outside_a_helper",
       {
           {R"~(Program([
  Function("f" true [] [
    SetDecimal
    ClearDecimal
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': SetDecimal outside a runtime helper; ClearDecimal outside a runtime helper)~"},
       }},
      // The 6502 has INC, DEC, and the shifts of abs,X and no abs,Y.
      {"read_modify_write_of_an_element_by_y",
       {
           {R"~(Program([
  Function("f" true [] [
    Inc(IndexedData("t" 2 Y))
    Dec(IndexedData("t" 2 Y))
    ArithmeticShiftLeft(IndexedData("t" 2 Y))
    LogicalShiftRight(IndexedData("t" 2 Y))
    RotateLeft(IndexedData("t" 2 X))
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': Inc of IndexedData(name='t', offset=2, index=Y()), which has no 6502 addressing mode (only abs,X); Dec of IndexedData(name='t', offset=2, index=Y()), which has no 6502 addressing mode (only abs,X); ArithmeticShiftLeft of IndexedData(name='t', offset=2, index=Y()), which has no 6502 addressing mode (only abs,X); LogicalShiftRight of IndexedData(name='t', offset=2, index=Y()), which has no 6502 addressing mode (only abs,X))~"},
           {R"~(Program([
  Function("f" true [] [
    RotateRight(IndexedData("t" 2 Y))
  ])
])
)~",
            false, false,
            R"~(after test, function 'f': RotateRight of IndexedData(name='t', offset=2, index=Y()), which has no 6502 addressing mode (only abs,X))~"},
           {R"~(Program([
  Function("f" true [] [
    Inc(IndexedData("t" 2 X))
    Dec(IndexedData("t" 2 X))
  ])
])
)~",
            false, false,
            R"~()~"},
       }},
      // The message names the first function with a problem.
      {"first_function_with_a_problem",
       {
           {R"~(Program([
  Function("f" true [] [
    Label(".a")
  ])
  StaticVariable("s" false [])
  Function("g" true [] [
    Branch(NE ".a")
  ])
  Function("h" true [] [
    Branch(NE ".b")
  ])
])
)~",
            false, false,
            R"~(after test, function 'g': branch to missing label .a)~"},
       }},
  };
  return cases;
}

inline const std::vector<Case<RegionCheck>>& region_cases() {
  static const std::vector<Case<RegionCheck>> cases = {
      // test_bcd_builtins.py's TestIrCheck.
      {"accepts_a_chain",
       {
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Add(Imm(1) Reg(A))
  Mov(Reg(A) Data("x" 0))
  ClearDecimal
])
)~",
            R"~()~"},
       }},
      {"rejects_code_inside_the_region",
       {
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Add(Imm(1) Reg(A))
  Mov(Reg(A) Data("x" 0))
  Call("f")
  ClearDecimal
])
)~",
            R"~(Call at 5 runs with the decimal flag set (SED at 0); CLD at 6 outside a BCD chain)~"},
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Add(Imm(1) Reg(A))
  Mov(Reg(A) Data("x" 0))
  Add(Imm(1) Reg(A))
  ClearDecimal
])
)~",
            R"~(Add at 5 runs with the decimal flag set (SED at 0); CLD at 6 outside a BCD chain)~"},
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Sub(Imm(1) Reg(A))
  Mov(Reg(A) Data("x" 0))
  ClearDecimal
])
)~",
            R"~(the BCD chain at 0 has no byte; Mov at 2 runs with the decimal flag set (SED at 0); CLD at 5 outside a BCD chain)~"},
       }},
      {"rejects_an_unclosed_or_stray_flag",
       {
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Add(Imm(1) Reg(A))
  Mov(Reg(A) Data("x" 0))
])
)~",
            R"~(the end at 5 runs with the decimal flag set (SED at 0))~"},
           {R"~(Function("f" true [] [
  ClearDecimal
])
)~",
            R"~(CLD at 0 outside a BCD chain)~"},
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  ClearDecimal
])
)~",
            R"~(the BCD chain at 0 has no byte)~"},
       }},
      {"rejects_a_register_operand",
       {
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Add(Reg(X) Reg(A))
  Mov(Reg(A) Data("x" 0))
  ClearDecimal
])
)~",
            R"~(the BCD chain at 0 has no byte; Mov at 2 runs with the decimal flag set (SED at 0); CLD at 5 outside a BCD chain)~"},
       }},
      {"accepts_a_subtract_of_two_bytes",
       {
           {R"~(Function("f" true [] [
  SetDecimal
  SetCarry
  Mov(Frame(3) Reg(A))
  Sub(ImmLabelLow("t" 0) Reg(A))
  Mov(Reg(A) Stack(1))
  Mov(ZP(128 1) Reg(A))
  Sub(ImmLabelHigh("t" 0) Reg(A))
  Mov(Reg(A) ZP(130 0))
  ClearDecimal
])
)~",
            R"~()~"},
       }},
      // The SED's region ends at once, and the CLD after it is stray.
      {"sed_without_clc_or_sec",
       {
           {R"~(Function("f" true [] [
  SetDecimal
  Return
  ClearDecimal
])
)~",
            R"~(SED at 0 isn't followed by CLC or SEC; CLD at 2 outside a BCD chain)~"},
           {R"~(Function("f" true [] [
  SetDecimal
])
)~",
            R"~(SED at 0 isn't followed by CLC or SEC)~"},
       }},
      {"a_store_to_an_immediate",
       {
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Add(Imm(1) Reg(A))
  Mov(Reg(A) Imm(0))
  ClearDecimal
])
)~",
            R"~(the BCD chain at 0 has no byte; Mov at 2 runs with the decimal flag set (SED at 0); CLD at 5 outside a BCD chain)~"},
       }},
      {"two_chains",
       {
           {R"~(Function("f" true [] [
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Add(Imm(1) Reg(A))
  Mov(Reg(A) Data("x" 0))
  ClearDecimal
  SetDecimal
  ClearCarry
  Mov(Data("x" 0) Reg(A))
  Add(Imm(1) Reg(A))
  Mov(Reg(A) Data("x" 0))
  ClearDecimal
])
)~",
            R"~()~"},
       }},
  };
  return cases;
}

inline const std::vector<Case<Asm2Check>>& asm2_cases() {
  static const std::vector<Case<Asm2Check>> cases = {
      // A runtime helper that sets the flag itself passes with a CLD before
      // each RTS, and a function of another name doesn't.
      {"helper_clears_the_flag_before_rts",
       {
           {R"~(Program([
  Function("bin16_to_bcd" true [] [
    SetDecimal
    ClearDecimal
    Return
  ])
])
)~",
            R"~()~"},
           {R"~(Program([
  StaticVariable("s" false [])
  Function("g" true [] [
    SetDecimal
    ClearDecimal
    Return
  ])
])
)~",
            R"~(after test, function 'g': SED at 0 isn't followed by CLC or SEC; CLD at 1 outside a BCD chain)~"},
       }},
      {"helper_without_cld_or_final_rts",
       {
           {R"~(Program([
  Function("bin16_to_bcd" true [] [
    SetDecimal
    Return
    Call("g")
  ])
])
)~",
            R"~(after test, function 'bin16_to_bcd': RTS at 1 without a CLD before it; the helper doesn't end with an RTS)~"},
           {R"~(Program([
  Function("bin16_to_bcd" true [] [])
])
)~",
            R"~()~"},
       }},
      // A compiled function of the helper's name passes by the chain's rule.
      {"compiled_function_of_a_helpers_name",
       {
           {R"~(Program([
  Function("bin16_to_bcd" true [] [
    SetDecimal
    ClearCarry
    Mov(Data("x" 0) Reg(A))
    Add(Imm(1) Reg(A))
    Mov(Reg(A) Data("x" 0))
    ClearDecimal
    Return
  ])
])
)~",
            R"~()~"},
       }},
  };
  return cases;
}

}  // namespace c6502::testing::ir_check_cases
